contracts/Pantry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {FHE, ebool, euint8, euint64, externalEuint64} from "@fhevm/solidity/lib/FHE.sol";
import {ZamaEthereumConfig} from "@fhevm/solidity/config/ZamaConfig.sol";
import {IERC20} from "@openzeppelin/contracts/interfaces/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ConfidentialCroq} from "./ConfidentialCroq.sol";

/// @dev The slice of DoNotOpen the Pantry reads. Nothing here writes to it.
interface IDoNotOpen {
    struct Revealed {
        uint64 seed;
        uint8 state;
        uint8[5] traits;
        uint16 score;
        uint32 affection;
        bool golden;
    }

    /// @dev Encrypted "does `account` hold `tokenId`", allowed to the Pantry for the transaction.
    ///      The Pantry must be one of the collection's trusted readers.
    function isOwner(uint256 tokenId, address account) external returns (ebool);
    function status(uint256 tokenId) external view returns (uint8);
    /// @dev 1 is Alive: the "Vet Certified" badge.
    function aliveCheck(uint256 tokenId) external view returns (uint8);
    function contentsOf(uint256 tokenId) external view returns (Revealed memory);
}

/// @title Pantry
/// @notice Runs the croquette economy next to DO NOT OPEN, without touching it.
///         A holder feeds their sealed cat cCROQ. The croquettes are eaten: the cat puts on an
///         encrypted weight, and the meal is split between the collection's treasury, the game
///         reserve (which pays the daily purr, so croquettes go round) and the fire. Once the
///         box is opened, anyone weighs the cat: its weight becomes public and sets its build,
///         from thin to huge. Past a tolerance of its own, drawn from its seed and unknown to
///         all until then, the cat is sick: an ultra-rare trophy. Holders also collect a
///         welcome bag and a daily purr.
///
/// @dev Design notes.
///
///  1. Every croquette the Pantry holds belongs to exactly one encrypted bucket: the reserve
///     (welcome bags and purrs), the treasury's share, or the burnt pile. A meal leaves nothing
///     behind: its croquettes all go to one of the three. The Pantry's cCROQ balance always
///     equals the three buckets.
///
///  2. NOBODY is allowed on a weight, the reserve or the burnt pile, holder and deployer
///     included. FHE.allow grants are permanent, so a weight readable by its holder would stay
///     readable by every past holder after a sale. The weight is made public only once the box
///     is opened. A feeder may read what their own meals added today. The treasury reads its share
///     only as what `collect` pays it, at most once a week: a share readable after every meal
///     would tell it who fed which cat, and how much.
///
///  3. A cat eats at most `mealsPerDay` meals and `maxEatenPerDay` croquettes per UTC day,
///     however they are spread. Who holds a box is encrypted (see `ConfidentialERC721`), so
///     the holder check, the meal count and the amount are all encrypted: a meal past the
///     limits, or served by someone who does not hold the cat, moves 0, silently. Nothing
///     about a meal reverts on them, and the meal count is not public.
///
///  4. A feeder who holds less than the (capped) offer moves 0. The meal still counts, still
///     costs gas, and nothing on-chain tells it apart from a real one.
///
///  7. Welcome bags and purrs are paid into the box, not to whoever asks: `claim` first tops up
///     each listed box's encrypted stash (anyone may, the clock is public), then pays the caller
///     the stashes of the boxes they hold, and 0 for the others. So nobody can spend another
///     holder's day, and a claim says nothing about what the caller holds.
///
///  5. The tolerance is keccak256 of the seed, folded into [sickMinWeight, +sickWeightSpread).
///     The seed is encrypted until the box is opened, and by then the weight is final: nobody,
///     the holder included, can feed a cat up to just its tolerance.
///
///  6. "Burnt" means locked here for good: no function moves the burnt pile. Real burning would
///     strand the same ERC-20 inside the wrapper anyway, at a higher FHE cost.
///
///  HCU per function (protocol limit 20,000,000 per transaction), measured in tests:
///    feed            ~2,790,000 first meal of the day, ~3,180,000 the second (one more sub)
///                    confidential transferFrom, the daily cap, two mul + div for the split
///    claim           ~680,000 per purring box, ~6.8M for the 10-box maximum
///                    0 once the purr has halved to nothing
///    weigh           0: one public decryption request, the rest is plain arithmetic
///    collect         ~590,000     one confidential transfer
contract Pantry is ZamaEthereumConfig {
    using SafeERC20 for IERC20;

    uint16 private constant BPS = 10_000;
    uint8 private constant SEALED = 0;
    uint8 private constant REVEALED = 1;

    uint8 public constant NOT_WEIGHED = 0;
    uint8 public constant WEIGH_PENDING = 1;
    uint8 public constant WEIGHED = 2;

    struct Params {
        /// Paid once per box, on its first claim.
        uint64 welcomeBag;
        /// A purr draws an encrypted amount in [0, purrMaxPerDay] per box and per day.
        uint8 purrMaxPerDay;
        /// Purr multiplier for Vet Certified boxes.
        uint8 vetMultiplier;
        /// Days of purr one claim can collect; older days are lost.
        uint8 purrMaxDays;
        /// The purr halves every `halvingPeriod` seconds after deployment.
        uint32 halvingPeriod;
        /// Meals one cat may eat per UTC day.
        uint8 mealsPerDay;
        /// Croquettes one cat may eat per UTC day, across all its meals.
        uint64 maxEatenPerDay;
        /// Share of each meal paid to the treasury.
        uint16 mealTreasuryBps;
        /// Share of each meal that is burnt. The rest goes back to the game reserve.
        uint16 mealBurnBps;
        /// Lowest weight of each build past "thin": normal, chubby, fat, huge. Increasing.
        uint64[4] buildFloors;
        /// A cat's tolerance is drawn in [sickMinWeight, sickMinWeight + sickWeightSpread).
        uint64 sickMinWeight;
        uint64 sickWeightSpread;
        /// Upper bounds, out of 65,536, of every disease but the last.
        uint16[2] diseaseRollBelow;
        /// Boxes one claim may cover, to keep it under the HCU limit.
        uint8 maxBoxesPerClaim;
    }

    /// @notice What the scales said, once a box is opened and weighed.
    struct WeighIn {
        uint8 status;
        /// 0 thin (never ate), 1 normal, 2 chubby, 3 fat, 4 huge.
        uint8 build;
        bool sick;
        /// Index into the spec's diseases. Meaningful only when `sick`.
        uint8 disease;
        uint64 weight;
        uint64 tolerance;
    }

    /// @dev What a feeder may read about today's meals of one cat: masked to 0 for a feeder who
    ///      does not hold it.
    struct Seen {
        uint32 day;
        euint8 meals;
        euint64 eaten;
    }

    error InvalidParams();
    error NotHolder();
    error NotSealed();
    error NotRevealed();
    error AlreadyWeighed();
    error WeighInNotPending();
    error NothingToClaim();
    error NothingToCollect();
    error InvalidBoxCount();
    error CollectTooSoon();

    event Funded(address indexed from, uint64 amount);
    event MealServed(uint256 indexed tokenId, address indexed feeder);
    event WelcomeBag(uint256 indexed tokenId);
    event Purred(uint256 indexed tokenId, uint256 days_);
    event Claimed(address indexed caller, uint256 boxes);
    event WeighInRequested(uint256 indexed tokenId, bytes32 weightHandle);
    event Weighed(uint256 indexed tokenId, uint64 weight, uint8 build, bool sick, uint8 disease);
    event Collected(address indexed treasury);

    IDoNotOpen public immutable boxes;
    ConfidentialCroq public immutable cCroq;
    IERC20 public immutable croq;
    /// @notice Receives the treasury's share of every meal, through `collect`.
    address public immutable treasury;
    uint256 public immutable startedAt;
    /// @notice The least time between two collections, so the treasury only ever learns its
    ///         share in weekly sums.
    uint64 public constant COLLECT_INTERVAL = 7 days;

    uint64 public immutable welcomeBag;
    uint8 public immutable purrMaxPerDay;
    uint8 public immutable vetMultiplier;
    uint8 public immutable purrMaxDays;
    uint32 public immutable halvingPeriod;
    uint8 public immutable mealsPerDay;
    uint64 public immutable maxEatenPerDay;
    uint16 public immutable mealTreasuryBps;
    uint16 public immutable mealBurnBps;
    uint64 public immutable sickMinWeight;
    uint64 public immutable sickWeightSpread;
    uint8 public immutable maxBoxesPerClaim;
    uint64 private immutable _floorNormal;
    uint64 private immutable _floorChubby;
    uint64 private immutable _floorFat;
    uint64 private immutable _floorHuge;
    uint16 private immutable _disease1;
    uint16 private immutable _disease2;

    euint64 private _reserve;
    euint64 private _burnt;
    euint64 private _treasuryShare;
    /// @notice When the treasury last collected (the deployment counts as one).
    uint64 public lastCollected;
    mapping(uint256 tokenId => euint64) private _weight;
    mapping(uint256 tokenId => euint64) private _eatenToday;
    mapping(uint256 tokenId => euint8) private _mealsToday;
    /// @dev The UTC day `_eatenToday` and `_mealsToday` are about.
    mapping(uint256 tokenId => uint32) private _day;
    mapping(uint256 tokenId => mapping(address feeder => Seen)) private _seen;
    /// @dev Welcome bag and purrs paid into a box, waiting for its holder.
    mapping(uint256 tokenId => euint64) private _stash;
    /// @notice When a box last purred. Zero until its welcome bag is collected.
    mapping(uint256 tokenId => uint64) public lastPurr;
    mapping(uint256 tokenId => WeighIn) private _weighIns;

    constructor(IDoNotOpen boxes_, ConfidentialCroq cCroq_, address treasury_, Params memory p) {
        if (
            treasury_ == address(0) ||
            p.purrMaxPerDay == type(uint8).max ||
            p.vetMultiplier == 0 ||
            p.purrMaxDays == 0 ||
            p.halvingPeriod == 0 ||
            p.mealsPerDay == 0 ||
            p.maxEatenPerDay == 0 ||
            uint256(p.mealTreasuryBps) + p.mealBurnBps > BPS ||
            p.buildFloors[0] == 0 ||
            p.buildFloors[1] <= p.buildFloors[0] ||
            p.buildFloors[2] <= p.buildFloors[1] ||
            p.buildFloors[3] <= p.buildFloors[2] ||
            p.sickMinWeight <= p.buildFloors[3] ||
            p.sickWeightSpread == 0 ||
            p.diseaseRollBelow[1] <= p.diseaseRollBelow[0] ||
            p.maxBoxesPerClaim == 0
        ) revert InvalidParams();

        boxes = boxes_;
        cCroq = cCroq_;
        croq = IERC20(cCroq_.underlying());
        treasury = treasury_;
        startedAt = block.timestamp;
        lastCollected = uint64(block.timestamp);
        welcomeBag = p.welcomeBag;
        purrMaxPerDay = p.purrMaxPerDay;
        vetMultiplier = p.vetMultiplier;
        purrMaxDays = p.purrMaxDays;
        halvingPeriod = p.halvingPeriod;
        mealsPerDay = p.mealsPerDay;
        maxEatenPerDay = p.maxEatenPerDay;
        mealTreasuryBps = p.mealTreasuryBps;
        mealBurnBps = p.mealBurnBps;
        sickMinWeight = p.sickMinWeight;
        sickWeightSpread = p.sickWeightSpread;
        maxBoxesPerClaim = p.maxBoxesPerClaim;
        _floorNormal = p.buildFloors[0];
        _floorChubby = p.buildFloors[1];
        _floorFat = p.buildFloors[2];
        _floorHuge = p.buildFloors[3];
        _disease1 = p.diseaseRollBelow[0];
        _disease2 = p.diseaseRollBelow[1];
    }

    // ------------------------------------------------------------------ fund

    /// @notice Adds plain CROQ to the game reserve. The caller must have approved the Pantry.
    ///         Public amount: it moves as a plain ERC-20 before being wrapped.
    function fund(uint64 amount) external {
        croq.safeTransferFrom(msg.sender, address(this), amount);
        croq.forceApprove(address(cCroq), amount);
        cCroq.wrap(address(this), amount);

        euint64 reserve = FHE.add(_reserve, amount);
        FHE.allowThis(reserve);
        _reserve = reserve;
        emit Funded(msg.sender, amount);
    }


    // ------------------------------------------------------------------ feed

    /// @notice The holder feeds their sealed cat an encrypted amount of cCROQ. The cat eats it
    ///         all: its hidden weight goes up, and the croquettes are split between the
    ///         treasury, the game reserve and the fire. At most `mealsPerDay` meals and
    ///         `maxEatenPerDay` croquettes a day; an offer past what is left of the day is cut
    ///         down to it, and a meal past the limits, or from someone who does not hold the cat,
    ///         moves 0. The caller must have made the Pantry an operator on cCROQ.
    /// @param amount encrypted amount, made for this contract and the caller with the Relayer SDK
    /// @param inputProof the proof that comes with it
    function feed(uint256 tokenId, externalEuint64 amount, bytes calldata inputProof) external {
        if (boxes.status(tokenId) != SEALED) revert NotSealed();
        ebool holds = boxes.isOwner(tokenId, msg.sender);

        uint32 today = uint32(block.timestamp / 1 days);
        if (_day[tokenId] != today) {
            _day[tokenId] = today;
            _mealsToday[tokenId] = FHE.asEuint8(0);
            _eatenToday[tokenId] = FHE.asEuint64(0);
        }
        ebool served = FHE.and(holds, FHE.lt(_mealsToday[tokenId], mealsPerDay));
        euint64 moved = _serve(tokenId, served, FHE.fromExternal(amount, inputProof));
        _countMeal(tokenId, today, holds, served, moved);

        euint64 weight = FHE.add(_weight[tokenId], moved);
        FHE.allowThis(weight);
        _weight[tokenId] = weight;

        _split(moved);
        emit MealServed(tokenId, msg.sender);
    }

    /// @dev Pulls the offer, cut down to what is left of the day, or 0 if the meal is not served.
    ///      Returns what arrived.
    function _serve(uint256 tokenId, ebool served, euint64 offered) internal returns (euint64) {
        euint64 left = FHE.sub(maxEatenPerDay, _eatenToday[tokenId]);
        euint64 capped = FHE.select(served, FHE.min(offered, left), FHE.asEuint64(0));
        FHE.allowTransient(capped, address(cCroq));
        // Moves `capped` if the caller holds it, 0 otherwise.
        return cCroq.confidentialTransferFrom(msg.sender, address(this), capped);
    }

    /// @dev Adds the meal to today's count and lets the feeder read back today's totals: the
    ///      real ones if they hold the cat, zeros otherwise.
    function _countMeal(uint256 tokenId, uint32 today, ebool holds, ebool served, euint64 moved) internal {
        euint8 meals = FHE.add(_mealsToday[tokenId], FHE.select(served, FHE.asEuint8(1), FHE.asEuint8(0)));
        euint64 eaten = FHE.add(_eatenToday[tokenId], moved);
        FHE.allowThis(meals);
        FHE.allowThis(eaten);
        _mealsToday[tokenId] = meals;
        _eatenToday[tokenId] = eaten;

        euint8 seenMeals = FHE.select(holds, meals, FHE.asEuint8(0));
        euint64 seenEaten = FHE.select(holds, eaten, FHE.asEuint64(0));
        FHE.allowThis(seenMeals);
        FHE.allowThis(seenEaten);
        FHE.allow(seenMeals, msg.sender);
        FHE.allow(seenEaten, msg.sender);
        _seen[tokenId][msg.sender] = Seen(today, seenMeals, seenEaten);
    }

    /// @notice Handles of what `feeder` may read about `tokenId` today: meals and croquettes
    ///         eaten, both 0 unless they hold it. Zero handles on a new day or for a stranger.
    function todayHandles(uint256 tokenId, address feeder) external view returns (bytes32 meals, bytes32 eaten) {
        Seen storage s = _seen[tokenId][feeder];
        if (s.day != uint32(block.timestamp / 1 days)) return (bytes32(0), bytes32(0));
        return (FHE.toBytes32(s.meals), FHE.toBytes32(s.eaten));
    }

    /// @notice Sends the treasury its share of every meal so far. Anyone may call it, at most
    ///         once per `COLLECT_INTERVAL`.
    function collect() external {
        euint64 owed = _treasuryShare;
        if (!FHE.isInitialized(owed)) revert NothingToCollect();
        if (block.timestamp < lastCollected + COLLECT_INTERVAL) revert CollectTooSoon();
        lastCollected = uint64(block.timestamp);
        euint64 zero = FHE.asEuint64(0);
        FHE.allowThis(zero);
        _treasuryShare = zero;
        _pay(treasury, owed);
        emit Collected(treasury);
    }

    // ----------------------------------------------------------------- claim

    /// @notice For each listed box: pays into it its welcome bag the first time, then its purr
    ///         for every whole day since (up to `purrMaxDays`), whoever asks. Then pays the caller,
    ///         as one encrypted cCROQ transfer, what waits in the listed boxes they hold.
    /// @dev One encrypted draw per purring box, multiplied by the days owed. When the reserve can
    ///      no longer pay a whole claim, that claim pays nothing into the boxes.
    function claim(uint256[] calldata tokenIds) external {
        uint256 count = tokenIds.length;
        if (count == 0 || count > maxBoxesPerClaim) revert InvalidBoxCount();

        uint256 era = (block.timestamp - startedAt) / halvingPeriod;
        euint64[] memory dues = new euint64[](count);
        euint64 totalDue;
        for (uint256 i = 0; i < count; i++) {
            dues[i] = _accrue(tokenIds[i], era);
            // An id nobody holds (a mint's empty ids) gets nothing: its stash could never be
            // claimed, and free empty ids would drain the reserve.
            if (FHE.isInitialized(dues[i])) dues[i] = FHE.select(boxes.isOwner(tokenIds[i], address(0)), FHE.asEuint64(0), dues[i]);
            if (FHE.isInitialized(dues[i])) totalDue = FHE.isInitialized(totalDue) ? FHE.add(totalDue, dues[i]) : dues[i];
        }
        // The reserve pays all of this claim or, once it can no longer, none of it.
        ebool funded;
        if (FHE.isInitialized(totalDue)) {
            funded = FHE.le(totalDue, _reserve);
            euint64 reserve = FHE.sub(_reserve, FHE.select(funded, totalDue, FHE.asEuint64(0)));
            FHE.allowThis(reserve);
            _reserve = reserve;
        }

        euint64 payout = FHE.asEuint64(0);
        bool anything;
        for (uint256 i = 0; i < count; i++) {
            uint256 tokenId = tokenIds[i];
            euint64 stash = _stash[tokenId];
            if (FHE.isInitialized(dues[i])) {
                euint64 paid = FHE.select(funded, dues[i], FHE.asEuint64(0));
                stash = FHE.isInitialized(stash) ? FHE.add(stash, paid) : paid;
            }
            if (!FHE.isInitialized(stash)) continue;
            anything = true;
            ebool owns = boxes.isOwner(tokenId, msg.sender);
            euint64 mine = FHE.select(owns, stash, FHE.asEuint64(0));
            // The holder takes it all: what stays is the stash, or nothing.
            stash = FHE.select(owns, FHE.asEuint64(0), stash);
            FHE.allowThis(stash);
            _stash[tokenId] = stash;
            payout = FHE.add(payout, mine);
        }
        if (!anything) revert NothingToClaim();
        _pay(msg.sender, payout);
        emit Claimed(msg.sender, count);
    }

    /// @dev What `tokenId` is owed since its last claim, moving its clock. Uninitialized when
    ///      nothing is owed or the purr has halved to nothing.
    function _accrue(uint256 tokenId, uint256 era) internal returns (euint64 due) {
        uint64 last = lastPurr[tokenId];
        if (last == 0) {
            lastPurr[tokenId] = uint64(block.timestamp);
            emit WelcomeBag(tokenId);
            return FHE.asEuint64(welcomeBag);
        }
        uint256 owed = (block.timestamp - last) / 1 days;
        if (owed == 0) return due;
        if (owed > purrMaxDays) {
            owed = purrMaxDays;
            lastPurr[tokenId] = uint64(block.timestamp);
        } else {
            // Keeps the part of a day already started.
            lastPurr[tokenId] = uint64(last + owed * 1 days);
        }
        emit Purred(tokenId, owed);

        uint256 factor = owed * (boxes.aliveCheck(tokenId) == 1 ? vetMultiplier : 1);
        // Past the point where even the best draw halves to zero, skip the FHE work.
        if (era >= 64 || (uint256(purrMaxPerDay) * factor) >> era == 0) return due;
        return _purrDraw(factor, uint8(era));
    }

    /// @dev Uniform-ish draw in [0, purrMaxPerDay] (a byte modulo n: 256 is not a multiple
    ///      of 5, so 0 is 1/256 more likely than the rest), times `factor`, halved `era` times.
    function _purrDraw(uint256 factor, uint8 era) internal returns (euint64 draw) {
        euint8 roll = FHE.rem(FHE.randEuint8(), purrMaxPerDay + 1);
        draw = FHE.asEuint64(roll);
        if (factor != 1) draw = FHE.mul(draw, uint64(factor));
        if (era != 0) draw = FHE.shr(draw, era);
    }

    // ----------------------------------------------------------------- weigh

    /// @notice Weighs an opened cat. Anyone may, once. A cat that never ate is weighed on the
    ///         spot; otherwise this makes its weight publicly decryptable, and `finalizeWeigh`
    ///         records it with the KMS proof.
    function weigh(uint256 tokenId) external {
        if (boxes.status(tokenId) != REVEALED) revert NotRevealed();
        if (_weighIns[tokenId].status != NOT_WEIGHED) revert AlreadyWeighed();

        euint64 weight = _weight[tokenId];
        if (!FHE.isInitialized(weight)) {
            _record(tokenId, 0);
            return;
        }
        _weighIns[tokenId].status = WEIGH_PENDING;
        FHE.makePubliclyDecryptable(weight);
        emit WeighInRequested(tokenId, FHE.toBytes32(weight));
    }

    /// @notice Step 2 of 2. Anyone may submit the decrypted weight with its KMS proof.
    function finalizeWeigh(uint256 tokenId, bytes calldata abiEncodedWeight, bytes calldata decryptionProof) external {
        if (_weighIns[tokenId].status != WEIGH_PENDING) revert WeighInNotPending();
        bytes32[] memory handles = new bytes32[](1);
        handles[0] = FHE.toBytes32(_weight[tokenId]);
        FHE.checkSignatures(handles, abiEncodedWeight, decryptionProof);
        _record(tokenId, abi.decode(abiEncodedWeight, (uint64)));
    }

    function _record(uint256 tokenId, uint64 weight) internal {
        // The seed is public once the box is open; until then nobody could compute this.
        uint256 h = uint256(keccak256(abi.encode(boxes.contentsOf(tokenId).seed)));
        uint64 tolerance = sickMinWeight + uint64(h % sickWeightSpread);
        bool sick = weight >= tolerance;
        uint8 disease;
        if (sick) {
            uint16 roll = uint16(h >> 128);
            disease = roll < _disease1 ? 0 : roll < _disease2 ? 1 : 2;
        }
        uint8 build = buildOf(weight);
        _weighIns[tokenId] = WeighIn(WEIGHED, build, sick, disease, weight, tolerance);
        emit Weighed(tokenId, weight, build, sick, disease);
    }

    /// @notice The build a weight gives: 0 thin, 1 normal, 2 chubby, 3 fat, 4 huge.
    function buildOf(uint64 weight) public view returns (uint8) {
        if (weight >= _floorHuge) return 4;
        if (weight >= _floorFat) return 3;
        if (weight >= _floorChubby) return 2;
        if (weight >= _floorNormal) return 1;
        return 0;
    }

    function weighIn(uint256 tokenId) external view returns (WeighIn memory) {
        return _weighIns[tokenId];
    }

    function buildFloors() external view returns (uint64[4] memory) {
        return [_floorNormal, _floorChubby, _floorFat, _floorHuge];
    }

    // ----------------------------------------------------------------- views

    /// @notice Handle of what waits in a box for its holder. Nobody may decrypt it: the holder
    ///         learns it by claiming.
    function stashHandle(uint256 tokenId) external view returns (bytes32) {
        return FHE.toBytes32(_stash[tokenId]);
    }

    /// @notice Handle of a cat's encrypted weight. A handle is an identifier, not the value:
    ///         nobody may decrypt it until `weigh` makes it public.
    function weightHandle(uint256 tokenId) external view returns (bytes32) {
        return FHE.toBytes32(_weight[tokenId]);
    }

    function reserveHandle() external view returns (bytes32) {
        return FHE.toBytes32(_reserve);
    }

    function burntHandle() external view returns (bytes32) {
        return FHE.toBytes32(_burnt);
    }

    /// @notice Handle of the treasury's uncollected share, readable by nobody.
    function treasuryShareHandle() external view returns (bytes32) {
        return FHE.toBytes32(_treasuryShare);
    }

    /// @notice When `tokenId` can next claim something: now for a box that never claimed.
    function nextClaimAt(uint256 tokenId) external view returns (uint256) {
        uint64 last = lastPurr[tokenId];
        return last == 0 ? block.timestamp : last + 1 days;
    }

    /// @notice How many times the purr has halved so far.
    function halvings() external view returns (uint256) {
        return (block.timestamp - startedAt) / halvingPeriod;
    }

    // -------------------------------------------------------------- internal

    /// @dev Treasury and fire take their share, rounded down; the reserve gets the rest, so the
    ///      three always add up to the meal.
    function _split(euint64 moved) internal {
        euint64 toTreasury = _share(moved, mealTreasuryBps);
        euint64 toFire = mealBurnBps == mealTreasuryBps ? toTreasury : _share(moved, mealBurnBps);

        euint64 share = FHE.add(_treasuryShare, toTreasury);
        FHE.allowThis(share);
        _treasuryShare = share;

        euint64 burnt = FHE.add(_burnt, toFire);
        FHE.allowThis(burnt);
        _burnt = burnt;

        euint64 reserve = FHE.add(_reserve, FHE.sub(FHE.sub(moved, toTreasury), toFire));
        FHE.allowThis(reserve);
        _reserve = reserve;
    }

    function _share(euint64 amount, uint16 bps) internal returns (euint64) {
        // Amounts are whole croquettes bounded by the 20M supply: amount * bps cannot overflow.
        return FHE.div(FHE.mul(amount, uint64(bps)), BPS);
    }

    function _pay(address to, euint64 amount) internal {
        FHE.allowTransient(amount, address(cCroq));
        cCroq.confidentialTransfer(to, amount);
    }
}

contracts/Rats.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {FHE, euint8, euint16} from "@fhevm/solidity/lib/FHE.sol";
import {ZamaEthereumConfig} from "@fhevm/solidity/config/ZamaConfig.sol";

/// @title The depot's rats
/// @notice Rats drawn in the studio, adopted as a plain ERC-721: nothing about a rat is secret,
///         unlike the boxes. A free rat is minted by its 64-bit seed, each seed once: its look is
///         recomputed from the seed by the game's generator. An AI rat is minted with its studio
///         job, each job once, on a signature of the app's backend (the attester), which has
///         stored its picture on Arweave and kept its 3D model first (`uri`). Paid in plain USDC, straight
///         to the treasury. Unrelated to the collection: it never reads or writes DoNotOpen.
///         The supply is capped for good, per kind, and each address mints at most `maxPerWallet`
///         rats: every rat earns croquettes from the RatPantry, which holds a fixed fund. The
///         whitelist's gifts (`giver`) adopt free seed rats for their wallets, outside the paid
///         rats' cap and the wallet limit, at most `maxGiftRats` of them.
///
///         The one secret: each rat's power, 1, 2 or 3, drawn encrypted at its mint with the
///         spec's odds. Its holder reads it (`allowPower` after a sale; the seller keeps reading
///         it, an access is never taken back). The rats' tricks (`RatTricks`) use it, encrypted:
///         1 sniffs boxes cheaper, 2 shields or jams one trait of a box, 3 all of them.
contract Rats is ERC721, Ownable, EIP712, ZamaEthereumConfig {
    using SafeERC20 for IERC20;

    enum Kind {
        Seed,
        Model
    }

    struct Rat {
        Kind kind;
        uint64 mintedAt;
        /// @dev The seed for a seed rat, the job id for an AI rat.
        bytes32 ref;
    }

    /// @notice A price above 100 USDC is refused, whatever the owner asks.
    uint256 public constant MAX_PRICE = 100_000_000;

    bytes32 private constant ADOPT_TYPEHASH = keccak256("Adopt(address minter,bytes32 job,string uri,uint256 deadline)");

    IERC20 public immutable usdc;
    address public treasury;
    /// @notice Signs AI rat adoptions once their files are on Arweave.
    address public attester;
    uint256 public seedPrice;
    uint256 public modelPrice;
    uint256 public totalSupply;
    /// @notice The most seed rats and AI rats there will ever be, set at deployment.
    uint256 public immutable maxSeedRats;
    uint256 public immutable maxModelRats;
    /// @notice The most rats one address may mint, both kinds together. Buying one is not limited.
    uint256 public immutable maxPerWallet;
    /// @notice The most free rats the giver may ever hand out.
    uint256 public immutable maxGiftRats;
    uint256 public seedMinted;
    uint256 public modelMinted;
    uint256 public giftMinted;
    /// @notice The whitelist's gifts contract, the only one that adopts rats for free. Zero: none.
    address public giver;
    mapping(address account => uint256) public mintedBy;
    /// @notice The rats' tricks, the only contract that computes with the powers. Zero: none.
    address public tricks;
    /// @dev A 16-bit draw below the first bound is power 1, below the second power 2, else 3.
    uint16 private immutable _power1Below;
    uint16 private immutable _power2Below;
    mapping(uint256 tokenId => euint8) private _power;

    mapping(uint256 tokenId => Rat) private _rats;
    /// @notice The rat minted from a seed or a job, or 0. Token ids start at 1.
    mapping(uint64 seed => uint256) public tokenOfSeed;
    mapping(bytes32 job => uint256) public tokenOfJob;

    string private _base;

    error AlreadyAdopted();
    error PriceChanged();
    error PriceTooHigh();
    error ZeroPrice();
    error ZeroAddress();
    error Expired();
    error BadSignature();
    error SoldOut();
    error WalletLimit();
    error ZeroCap();
    error NotGiver();
    error NotTricks();
    error NotYourRat();
    error BadOdds();

    event RatMinted(uint256 indexed tokenId, address indexed minter, Kind kind, bytes32 ref, string uri, uint256 paid);
    event PricesSet(uint256 seedPrice, uint256 modelPrice);
    event TreasurySet(address treasury);
    event AttesterSet(address attester);
    event BaseURISet(string baseURI);
    event GiverSet(address giver);
    event TricksSet(address tricks);

    constructor(
        IERC20 usdc_,
        address treasury_,
        address owner_,
        address attester_,
        uint256 seedPrice_,
        uint256 modelPrice_,
        string memory baseURI_,
        uint256[4] memory caps_,
        uint16[2] memory powerBelow_
    ) ERC721("DO NOT OPEN Rats", "DNORAT") Ownable(owner_) EIP712("DO NOT OPEN Rats", "1") {
        usdc = usdc_;
        _setTreasury(treasury_);
        _setAttester(attester_);
        _setPrices(seedPrice_, modelPrice_);
        _base = baseURI_;
        // maxSeedRats, maxModelRats, maxPerWallet, maxGiftRats.
        if (caps_[0] == 0 || caps_[1] == 0 || caps_[2] == 0) revert ZeroCap();
        maxSeedRats = caps_[0];
        maxModelRats = caps_[1];
        maxPerWallet = caps_[2];
        maxGiftRats = caps_[3];
        if (powerBelow_[0] == 0 || powerBelow_[1] < powerBelow_[0]) revert BadOdds();
        _power1Below = powerBelow_[0];
        _power2Below = powerBelow_[1];
    }

    /// @notice Adopts the free rat of `seed`, at most `maxPrice` USDC. The caller must have
    ///         approved this contract for the price.
    function mintSeed(uint64 seed, uint256 maxPrice) external returns (uint256 tokenId) {
        if (tokenOfSeed[seed] != 0) revert AlreadyAdopted();
        if (++seedMinted > maxSeedRats) revert SoldOut();
        tokenId = ++totalSupply;
        tokenOfSeed[seed] = tokenId;
        _adopt(tokenId, Kind.Seed, bytes32(uint256(seed)), "", seedPrice, maxPrice);
    }

    /// @notice Adopts the AI rat of studio job `job`, whose files the attester put at `uri`.
    ///         The attester's signature names the caller, so nobody else can mint it.
    function mintModel(bytes32 job, string calldata uri, uint256 deadline, bytes calldata signature, uint256 maxPrice) external returns (uint256 tokenId) {
        if (block.timestamp > deadline) revert Expired();
        if (tokenOfJob[job] != 0) revert AlreadyAdopted();
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(ADOPT_TYPEHASH, msg.sender, job, keccak256(bytes(uri)), deadline)));
        if (ECDSA.recover(digest, signature) != attester) revert BadSignature();
        if (++modelMinted > maxModelRats) revert SoldOut();
        tokenId = ++totalSupply;
        tokenOfJob[job] = tokenId;
        _adopt(tokenId, Kind.Model, job, uri, modelPrice, maxPrice);
    }

    /// @notice The giver adopts the free rat of `seed` for `to`, without payment, once per seed.
    function gift(address to, uint64 seed) external returns (uint256 tokenId) {
        if (msg.sender != giver || giver == address(0)) revert NotGiver();
        if (to == address(0)) revert ZeroAddress();
        if (tokenOfSeed[seed] != 0) revert AlreadyAdopted();
        if (++giftMinted > maxGiftRats) revert SoldOut();
        tokenId = ++totalSupply;
        tokenOfSeed[seed] = tokenId;
        _rats[tokenId] = Rat(Kind.Seed, uint64(block.timestamp), bytes32(uint256(seed)));
        _drawPower(tokenId, to);
        _mint(to, tokenId);
        emit RatMinted(tokenId, to, Kind.Seed, bytes32(uint256(seed)), "", 0);
    }

    /// @notice Handle of the rat's encrypted power. Its holder decrypts it once allowed.
    function powerOf(uint256 tokenId) external view returns (bytes32) {
        _requireOwned(tokenId);
        return FHE.toBytes32(_power[tokenId]);
    }

    /// @notice Lets the rat's holder read its power, after buying it.
    function allowPower(uint256 tokenId) external {
        if (ownerOf(tokenId) != msg.sender) revert NotYourRat();
        FHE.allow(_power[tokenId], msg.sender);
    }

    /// @notice Whether `account` may decrypt the rat's power: its minter, and whoever called
    ///         `allowPower` while holding it.
    function powerReadableBy(uint256 tokenId, address account) external view returns (bool) {
        return FHE.isAllowed(_power[tokenId], account);
    }

    /// @notice The power, for the tricks' computation in this transaction only.
    function powerFor(uint256 tokenId) external returns (euint8 power) {
        if (msg.sender != tricks || tricks == address(0)) revert NotTricks();
        _requireOwned(tokenId);
        power = _power[tokenId];
        FHE.allowTransient(power, msg.sender);
    }

    function ratOf(uint256 tokenId) external view returns (Rat memory) {
        _requireOwned(tokenId);
        return _rats[tokenId];
    }

    /// @notice When the rat was minted: its croquettes count from there.
    function mintedAt(uint256 tokenId) external view returns (uint64) {
        _requireOwned(tokenId);
        return _rats[tokenId].mintedAt;
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        return string.concat(_base, Strings.toString(tokenId));
    }

    function setPrices(uint256 seedPrice_, uint256 modelPrice_) external onlyOwner {
        _setPrices(seedPrice_, modelPrice_);
    }

    function setTreasury(address treasury_) external onlyOwner {
        _setTreasury(treasury_);
    }

    function setAttester(address attester_) external onlyOwner {
        _setAttester(attester_);
    }

    function setGiver(address giver_) external onlyOwner {
        giver = giver_;
        emit GiverSet(giver_);
    }

    function setTricks(address tricks_) external onlyOwner {
        tricks = tricks_;
        emit TricksSet(tricks_);
    }

    function setBaseURI(string calldata baseURI_) external onlyOwner {
        _base = baseURI_;
        emit BaseURISet(baseURI_);
    }

    function _adopt(uint256 tokenId, Kind kind, bytes32 ref, string memory uri, uint256 price, uint256 maxPrice) private {
        if (price > maxPrice) revert PriceChanged();
        if (++mintedBy[msg.sender] > maxPerWallet) revert WalletLimit();
        _rats[tokenId] = Rat(kind, uint64(block.timestamp), ref);
        _drawPower(tokenId, msg.sender);
        usdc.safeTransferFrom(msg.sender, treasury, price);
        // _mint, not _safeMint: no call into the receiver, so nothing can re-enter.
        _mint(msg.sender, tokenId);
        emit RatMinted(tokenId, msg.sender, kind, ref, uri, price);
    }

    /// @dev One encrypted 16-bit draw folded into 1, 2 or 3 with the spec's odds. Nobody can
    ///      predict or grind it: it is drawn under encryption, after the payment is decided.
    function _drawPower(uint256 tokenId, address holder) private {
        euint16 draw = FHE.randEuint16();
        euint8 power = FHE.select(FHE.lt(draw, _power1Below), FHE.asEuint8(1), FHE.select(FHE.lt(draw, _power2Below), FHE.asEuint8(2), FHE.asEuint8(3)));
        FHE.allowThis(power);
        FHE.allow(power, holder);
        _power[tokenId] = power;
    }

    function _setPrices(uint256 seedPrice_, uint256 modelPrice_) private {
        if (seedPrice_ > MAX_PRICE || modelPrice_ > MAX_PRICE) revert PriceTooHigh();
        // A free rat could be minted by the thousand to farm the croquettes.
        if (seedPrice_ == 0 || modelPrice_ == 0) revert ZeroPrice();
        seedPrice = seedPrice_;
        modelPrice = modelPrice_;
        emit PricesSet(seedPrice_, modelPrice_);
    }

    function _setTreasury(address treasury_) private {
        if (treasury_ == address(0)) revert ZeroAddress();
        treasury = treasury_;
        emit TreasurySet(treasury_);
    }

    function _setAttester(address attester_) private {
        if (attester_ == address(0)) revert ZeroAddress();
        attester = attester_;
        emit AttesterSet(attester_);
    }
}

contracts/RatTricks.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {FHE, ebool, euint8, euint64, externalEuint8} from "@fhevm/solidity/lib/FHE.sol";
import {ZamaEthereumConfig} from "@fhevm/solidity/config/ZamaConfig.sol";
import {IERC7984} from "@openzeppelin/confidential-contracts/interfaces/IERC7984.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IShakeGuard} from "./IShakeGuard.sol";

/// @dev The slice of DoNotOpen the tricks use.
interface ITrickBoxes {
    function isOwner(uint256 tokenId, address account) external returns (ebool);
    function paidShake(uint256 tokenId) external returns (euint8 pick, euint8 roll);
    function paidShakeFee() external view returns (uint64);
    function status(uint256 tokenId) external view returns (uint8);
}

/// @dev The slice of Rats the tricks use.
interface ITrickRats {
    function ownerOf(uint256 tokenId) external view returns (address);
    function powerFor(uint256 tokenId) external returns (euint8);
}

/// @dev The trait offsets inside a box's seed.
interface ITrickConfig {
    function traitOffsets() external view returns (uint8[5] memory);
}

/// @title The rats' tricks
/// @notice What a rat does with its encrypted power (1, 2 or 3), which nobody but its holder knows.
///
///         Sniff: the rat shakes a box for its holder, a paid shake. Every rat sniffs at the full
///         price; a power-1 rat gets `sniffRebate` back from the treasury, under encryption, so
///         nobody sees which rats sniff cheaper.
///
///         Trick: the rat is set on a box for `trickDuration`, then rests `recharge`. The contract
///         decides under encryption what it did. On a box its holder holds, it SHIELDS: strangers'
///         paid shakes (and rats' sniffs) of the blocked traits read a fake roll, the same one every
///         time. On someone else's box, it JAMS: the holder's own shakes of the blocked traits read
///         SCRAMBLED. Power 2 blocks the one trait its holder picked (encrypted), power 3 all five,
///         power 1 nothing: a bluff. A box fully shielded resists jams until its shield ends.
///
///         Every rat has the same button, the same duration and the same rest, so the chain only
///         shows "rat r was set on box b": not whether it shielded or jammed, nor its power, nor
///         the trait.
/// @dev DoNotOpen passes every shake through `filter` (it is DoNotOpen's guard), and lets this
///      contract ask `isOwner` (trusted reader). Rats lets it read powers (`setTricks`).
///
///  HCU, measured in tests (protocol limit 20,000,000 per transaction): see the README table.
contract RatTricks is IShakeGuard, ZamaEthereumConfig, Ownable {
    /// @notice A jammed shake's pick: no trait sits at this offset, so the app can tell.
    uint8 public constant SCRAMBLED = 254;

    struct Effect {
        /// 0xFF over each blocked trait's byte of the seed.
        euint64 mask;
        /// When it ends, encrypted: writing it in the clear would show which slot a trick filled.
        euint64 until;
        /// Shields only: the fake rolls, one byte per trait, drawn when the shield starts.
        euint64 noise;
    }

    struct Sniff {
        euint8 pick;
        euint8 roll;
    }

    ITrickBoxes public immutable boxes;
    ITrickRats public immutable rats;
    IERC7984 public immutable cUsdc;
    uint64 public immutable sniffFee;
    uint64 public immutable sniffRebate;
    uint64 public immutable trickDuration;
    uint64 public immutable recharge;
    /// @dev 0xFF over all five traits' bytes.
    uint64 private immutable _allTraits;
    uint8 private immutable _offset0;
    uint8 private immutable _offset1;
    uint8 private immutable _offset2;
    uint8 private immutable _offset3;
    uint8 private immutable _offset4;

    /// @notice Pays power-1 rebates from its cUSDC, once it made this contract its operator.
    address public rebater;

    /// @notice When the rat can play a trick again.
    mapping(uint256 ratId => uint64) public readyAt;
    mapping(uint256 tokenId => Effect) private _shield;
    mapping(uint256 tokenId => Effect) private _jam;
    mapping(uint256 tokenId => mapping(address sniffer => Sniff)) private _sniffs;

    error NotYourRat();
    error Recharging(uint64 readyAt);
    error NotSealed();
    error OnlyBoxes();
    error ZeroAddress();
    error BadParams();

    /// @notice The rat sniffed the box for its holder. What it read is theirs only.
    event Sniffed(uint256 indexed ratId, uint256 indexed tokenId, address indexed sniffer);
    /// @notice The rat was set on the box until `until`, and rests until `readyAt`. Shield, jam
    ///         or bluff: encrypted.
    event TrickPlayed(uint256 indexed ratId, uint256 indexed tokenId, address indexed player, uint64 until, uint64 readyAt);
    event RebaterSet(address rebater);

    constructor(
        ITrickBoxes boxes_,
        ITrickRats rats_,
        IERC7984 cUsdc_,
        ITrickConfig config_,
        uint64 sniffRebate_,
        uint64 trickDuration_,
        uint64 recharge_,
        address rebater_,
        address owner_
    ) Ownable(owner_) {
        if (address(boxes_) == address(0) || address(rats_) == address(0) || address(cUsdc_) == address(0)) revert ZeroAddress();
        boxes = boxes_;
        rats = rats_;
        cUsdc = cUsdc_;
        sniffFee = boxes_.paidShakeFee();
        if (sniffRebate_ > sniffFee || trickDuration_ == 0) revert BadParams();
        sniffRebate = sniffRebate_;
        trickDuration = trickDuration_;
        recharge = recharge_;
        uint8[5] memory offsets = config_.traitOffsets();
        _offset0 = offsets[0];
        _offset1 = offsets[1];
        _offset2 = offsets[2];
        _offset3 = offsets[3];
        _offset4 = offsets[4];
        uint64 all;
        for (uint256 i = 0; i < 5; i++) all |= uint64(0xFF) << offsets[i];
        _allTraits = all;
        rebater = rebater_;
        // DoNotOpen pulls each sniff's fee from here.
        cUsdc_.setOperator(address(boxes_), type(uint48).max);
    }

    // ----------------------------------------------------------------- sniff

    /// @notice The rat sniffs `tokenId` for its holder: a paid shake, at `sniffFee` cUSDC, whose
    ///         pick and roll only the caller can read (`lastSniff`). A power-1 rat gets
    ///         `sniffRebate` back. The caller must have made this contract an operator on cUSDC.
    function sniff(uint256 ratId, uint256 tokenId) external returns (euint8 pick, euint8 roll) {
        if (rats.ownerOf(ratId) != msg.sender) revert NotYourRat();
        euint64 fee = FHE.asEuint64(sniffFee);
        FHE.allowTransient(fee, address(cUsdc));
        euint64 paid = cUsdc.confidentialTransferFrom(msg.sender, address(this), fee);
        // Nothing else rests here, so DoNotOpen's pull only succeeds when the caller paid.
        (pick, roll) = boxes.paidShake(tokenId);
        FHE.allow(pick, msg.sender);
        FHE.allow(roll, msg.sender);
        _sniffs[tokenId][msg.sender] = Sniff(pick, roll);

        address from = rebater;
        if (sniffRebate != 0 && from != address(0) && cUsdc.isOperator(from, address(this))) {
            ebool cheap = FHE.and(FHE.eq(paid, fee), FHE.eq(rats.powerFor(ratId), 1));
            euint64 rebate = FHE.select(cheap, FHE.asEuint64(sniffRebate), FHE.asEuint64(0));
            FHE.allowTransient(rebate, address(cUsdc));
            cUsdc.confidentialTransferFrom(from, msg.sender, rebate);
        }
        emit Sniffed(ratId, tokenId, msg.sender);
    }

    /// @notice Handles of `sniffer`'s latest sniff of `tokenId`. Zero if none.
    function lastSniff(uint256 tokenId, address sniffer) external view returns (bytes32 pick, bytes32 roll) {
        Sniff storage s = _sniffs[tokenId][sniffer];
        return (FHE.toBytes32(s.pick), FHE.toBytes32(s.roll));
    }

    // ----------------------------------------------------------------- trick

    /// @notice Sets the rat on a sealed box for `trickDuration`. `trait` (0 to 4, encrypted for
    ///         this contract and the caller) is the one a power-2 rat blocks; ignored otherwise.
    function trick(uint256 ratId, uint256 tokenId, externalEuint8 trait, bytes calldata inputProof) external {
        if (rats.ownerOf(ratId) != msg.sender) revert NotYourRat();
        uint64 ready = readyAt[ratId];
        if (block.timestamp < ready) revert Recharging(ready);
        if (boxes.status(tokenId) != 0) revert NotSealed();
        uint64 until = uint64(block.timestamp) + trickDuration;
        ready = until + recharge;
        readyAt[ratId] = ready;

        euint8 power = rats.powerFor(ratId);
        euint64 effect = FHE.select(
            FHE.eq(power, 3),
            FHE.asEuint64(_allTraits),
            FHE.select(FHE.eq(power, 2), _traitMask(FHE.fromExternal(trait, inputProof)), FHE.asEuint64(0))
        );
        ebool holds = boxes.isOwner(tokenId, msg.sender);
        euint64 none = FHE.asEuint64(0);

        Effect storage shield = _shield[tokenId];
        // A box fully shielded resists jams.
        ebool fortified = FHE.and(_active(shield), FHE.eq(_orZero(shield.mask), _allTraits));
        _apply(shield, FHE.select(holds, effect, none), until, true);
        _apply(_jam[tokenId], FHE.select(FHE.or(holds, fortified), none, effect), until, false);
        emit TrickPlayed(ratId, tokenId, msg.sender, until, ready);
    }

    /// @dev 0xFF over trait `index`'s byte; above 4 counts as 4.
    function _traitMask(euint8 index) private returns (euint64) {
        euint8 offset = FHE.asEuint8(_offset4);
        offset = FHE.select(FHE.eq(index, 3), FHE.asEuint8(_offset3), offset);
        offset = FHE.select(FHE.eq(index, 2), FHE.asEuint8(_offset2), offset);
        offset = FHE.select(FHE.eq(index, 1), FHE.asEuint8(_offset1), offset);
        offset = FHE.select(FHE.eq(index, 0), FHE.asEuint8(_offset0), offset);
        return FHE.shl(FHE.asEuint64(0xFF), offset);
    }

    /// @dev Adds `effect` to the slot: an empty effect leaves it as it was; otherwise the blocked
    ///      traits join those still active and the end moves to `until`. A shield that starts
    ///      afresh draws new fake rolls.
    function _apply(Effect storage e, euint64 effect, uint64 until, bool shield) private {
        ebool empty = FHE.eq(effect, 0);
        ebool active = _active(e);
        euint64 mask = _orZero(e.mask);
        euint64 merged = FHE.or(FHE.select(active, mask, FHE.asEuint64(0)), effect);
        e.mask = FHE.select(empty, mask, merged);
        e.until = FHE.select(empty, _orZero(e.until), FHE.asEuint64(until));
        FHE.allowThis(e.mask);
        FHE.allowThis(e.until);
        if (shield) {
            euint64 noise = FHE.isInitialized(e.noise) ? e.noise : FHE.randEuint64();
            e.noise = FHE.select(FHE.or(empty, active), noise, FHE.randEuint64());
            FHE.allowThis(e.noise);
        }
    }

    function _active(Effect storage e) private returns (ebool) {
        return FHE.gt(_orZero(e.until), uint64(block.timestamp));
    }

    function _orZero(euint64 v) private returns (euint64) {
        return FHE.isInitialized(v) ? v : FHE.asEuint64(0);
    }

    // ---------------------------------------------------------------- filter

    /// @inheritdoc IShakeGuard
    /// @dev DoNotOpen only: anyone else could pass handles of their own and learn a box's mask.
    function filter(uint256 tokenId, bool paid, euint8 pick, euint8 roll) external returns (euint8, euint8) {
        if (msg.sender != address(boxes)) revert OnlyBoxes();
        Effect storage e = paid ? _shield[tokenId] : _jam[tokenId];
        if (FHE.isInitialized(e.mask)) {
            ebool hit = FHE.and(_active(e), FHE.ne(FHE.asEuint8(FHE.shr(e.mask, pick)), 0));
            if (paid) {
                roll = FHE.select(hit, FHE.asEuint8(FHE.shr(e.noise, pick)), roll);
            } else {
                pick = FHE.select(hit, FHE.asEuint8(SCRAMBLED), pick);
                roll = FHE.select(hit, FHE.asEuint8(0), roll);
            }
        }
        FHE.allowTransient(pick, msg.sender);
        FHE.allowTransient(roll, msg.sender);
        return (pick, roll);
    }

    // ----------------------------------------------------------------- admin

    function setRebater(address rebater_) external onlyOwner {
        rebater = rebater_;
        emit RebaterSet(rebater_);
    }
}

